ef\/ine $s(t)=\int_{0}^{t}|\gamma _{\xi}^{\prime}(u)|{\rm d}u$. Then any horizontal arc-length dif\/fers $s$ up to a constant. By the fundamental theorem
of calculus, we have $\frac{{\rm d}s}{{\rm d}t}=|\gamma _{\xi}^{\prime}(t)|$.
Since
\begin{gather*}
\frac{{\rm d}\gamma }{{\rm d}s}=\frac{{\rm d}\gamma }{{\rm d}t}\frac{{\rm d}t}{{\rm d}s}=\frac{\gamma ^{\prime}(t)}{|\gamma _{\xi}^{\prime}(t)|},
\end{gather*}
$\gamma _{\xi}^{\prime}(s)=\frac{\gamma _{\xi}^{{\prime}}(t)}{|\gamma _{\xi}^{\prime}(t)|}$, namely, $|\gamma _{\xi
}^{\prime}(s)|=1$.

A \textit{lift} of a mapping $f\colon M\rightarrow G/H$ is def\/ined to be a map $F\colon M\rightarrow G$ such that the following diagram commutes:
\begin{gather*}
 \xymatrix{ & G \ar[d]\\ M\ar[ur]^F \ar[r]_f & G/H, }
\end{gather*}
where $G$ is a Lie group, $H$ is a closed Lie subgroup and $G/H$ is the associated homogeneous space. In additional, another lift $\tilde{F}$ of $f$ has to satisfy
\begin{gather*}
\widetilde{F}(x) = F(x)g(x)
\end{gather*}
for some map $g\colon M\rightarrow H$.

et $\gamma(t)=(x(t),y(t),z(t))$ be a horizontally regular curve. The ho\-rizontal
arc-length $s$ is def\/ined by
\begin{gather*}
s(t)=\int_{0}^{t}|\gamma_{\xi}^{\prime}(u)|{\rm d}u.
\end{gather*}
We f\/irst observe that there is the natural decomposition
\begin{gather}
\gamma^{\prime}(t)=(x^{\prime}(t),y^{\prime}(t),z^{{\prime}}(t))=x^{\prime}(t)\frac{\partial}{\partial x}+y^{\prime}(t)\frac{\partial}{\partial y}+z^{\prime}(t)\frac{\partial}{\partial z} \nonumber\\
\hphantom{\gamma^{\prime}(t)}{} =
\underbrace{x^{\prime}(t)\mathring{e}_{1}+y^{\prime}(t)\mathring{e}_{2}}_{\gamma'_\xi(t)}+\underbrace{(z^{{\prime}}(t)+xy^{\prime}(t)-yx^{\prime}(t))\frac{\partial}{\partial z}}_{\gamma'_T(t)},\label{velexp}
\end{gather}
where we abuse the notation by $\frac{\partial}{\partial z}=T$. Let $\bar{\gamma}(s)$ be the reparametrization of $\gamma(t)$ by the horizontal arc-length~$s$. Since $\gamma^{\prime}(t)=\bar{\gamma}^{\prime}(s)\frac{{\rm d}s}{{\rm d}t}$, by comparing with the decomposition~(\ref{velexp}), one has
\begin{gather}
\bar{\gamma}_{\xi}^{\prime}(s)=\frac{{\rm d}t}{{\rm d}s}(x^{{\prime}}(t)\mathring{e}_{1}+y^{\prime}(\mathring{e}_{2})), \qquad
\bar{\gamma}_{T}^{\prime}(s)=\frac{{\rm d}t}{{\rm d}s}\big((z^{{\prime
}}(t)+xy^{\prime}(t)-yx^{\prime}(t))T\big).\label{velexp1}
\end{gather}

For the $p$-curvature, by (\ref{velexp1}), note that $X(s)=\frac{{\rm d}t}{{\rm d}s}(x^{\prime}(t)\mathring{e}_{1}+y^{\prime}(t)\mathring{e}_{2})$, and $Y(s)=JX(s)=\frac{{\rm d}t}{{\rm d}s}(x^{\prime}(t)\mathring{e}_{2}-y^{\prime}(t)\mathring{e}_{1})$. A straight-forward computation shows
\begin{gather*}
\frac{{\rm d}X(s)}{{\rm d}s} =\frac{{\rm d}}{{\rm d}s}\left(\frac{{\rm d}t}{{\rm d}s}\left(x^{\prime}(t),y^{\prime}(t),x^{\prime}y(t)-xy^{\prime}(t)\right)\right)\\
\hphantom{\frac{{\rm d}X(s)}{{\rm d}s}}{} =\left(\frac{{\rm d}t}{{\rm d}s}\right)^{2}\left(x^{\prime\prime}(t),y^{{\prime\prime }}(t),x^{\prime\prime}y(t)-xy^{\prime\prime}(t)\right)+
\frac{{\rm d}^{2}t}{{\rm d}s^{2}}\left(x^{\prime}(t),y^{\prime}(t),x^{\prime}y(t)-xy^{\prime}(t)\right) \\
\hphantom{\frac{{\rm d}X(s)}{{\rm d}s}}{}=\left(x^{\prime\prime}(t)\left(\frac{{\rm d}t}{{\rm d}s}\right)^{2}+x^{\prime}(t)\frac{{\rm d}^{2}t}{{\rm d}s^{2}}\right)\mathring{e}_{1}+ \left(y^{\prime\prime}(t)\left(\frac{{\rm d}t}{{\rm d}s}\right)^{2}+y^{\prime}(t)\frac{{\rm d}^{2}t}{{\rm d}s^{2}}\right)\mathring{e}_{2},
\end{gather*}
so
\begin{gather}
k(s)=\left\langle \frac{{\rm d}X(s)}{{\rm d}s},Y(s)\right\rangle \nonumber\\
\hphantom{k(s)}{} =-\left(x^{\prime\prime}(t)\left(\frac{{\rm d}t}{{\rm d}s}\right)^{2}+x^{\prime}(t)\frac{{\rm d}^{2}t}{{\rm d}s^{2}}\right)y^{\prime}(t)\frac{{\rm d}t}{{\rm d}s}
+\left(y^{\prime\prime}(t)\left(\frac{{\rm d}t}{{\rm d}s}\right)^{2}+y^{\prime}(t)\frac{{\rm d}^{2}t}{{\rm d}s^{2}}\right)x^{\prime}(t)\frac{{\rm d}t}{{\rm d}s} \nonumber\\
\hphantom{k(s)}{}=-\left(x^{\prime\prime}(t)y^{\prime}(t)-x^{\prime}(t)y^{\prime\prime}(t)\right)\left(\frac{{\rm d}t}{{\rm d}s}\right)^3
=\frac{x^{\prime}y^{\prime\prime}-x^{\prime\prime}y^{\prime}}{\big((x^{\prime})^{2}+(y^{\prime})^{2}\big)^{\frac{3}{2}}}(t).\label{pcur}
\end{gather}
Again by (\ref{velexp1}), the contact normality must be
\begin{gather}
\tau(s)=\langle \bar{\gamma}^{\prime}(s),T\rangle =\langle \bar{\gamma}_{T}^{\prime}(s),T\rangle=\frac{{\rm d}t}{{\rm d}s}(z^{\prime}(t)+xy^{\prime}(t)-yx^{\prime}(t)) =\frac{xy^{\prime}-x^{\prime}y+z^{\prime}}{\big((x^{\prime})^{2}+(y^{\prime})^{2}\big)^{\frac{1}{2}}}(t),\label{Tvai}
\end{gather}
and the result follows.

ecall \cite{CCG} that the Hamiltonian system on $H_{1}$ for the geodesics is
\begin{gather}\label{HS}
\dot{x}^{k}(t) = h^{kj} (x(t)) \xi_{j}(t), \qquad
\dot{\xi}_{k}(t) = -\frac{1}{2}\sum \limits_{i,j=1}^{3}\frac{\partial h^{ij}(x) }{\partial x^{k}}\xi _{i}\xi _{j},\qquad
k=1,2,3,
\end{gather}
where
\begin{gather*}
h^{ij}\big( x^{1},x^{2},x^{3}\big) =
\begin{pmatrix}
1 & 0 & x^{2} \\
0 & 1 & -x^{1} \\
x^{2} & -x^{1} & \big( x^{1}\big) ^{2}+\big( x^{2}\big) ^{2} 
\end{pmatrix}.
\end{gather*}
So the Hamiltonian system (\ref{HS}) can be expressed by
\begin{gather*}
\dot{x}^{1}(t) =\xi _{1}+x^{2}\xi _{3}, \\
\dot{x}^{2}(t) =\xi _{2}-x^{1}\xi _{3}, \\
\dot{x}^{3}(t) =x^{2}\xi _{1}-x^{1}\xi _{2}+\xi _{3}\big[\big( x^{1}\big) ^{2}+\big( x^{2}\big) ^{2}\big] ,\\
\dot{\xi}_{1}(t) =\xi _{2}\xi _{3}-x^{1}\xi _{3}^{2}, \\
\dot{\xi}_{2}(t) =-\xi _{1}\xi _{3}-x^{2}\xi _{3}^{2}, \\
\dot{\xi}_{3}(t) =0.
\end{gather*}
Since $\dot{\xi}_{3}(t) =0$, we have $\xi _{3}(t)
=c_{3} $ for some constant $c_{3}$. When $c_{3}=0$, one has
$x(t) =( c_{1}t+d_{1},c_{2}t+d_{2},(c_{1}d_{2}-c_{2}d_{1}) t+d_{3})$, and this implies that $k(t) =0$ and
$\tau (t) =0$; when $c_{3}> 0$, one has
\begin{gather}\label{gode1}
x(t) = \big( x^{1}(t) ,x^{2}(t),x^{3}(t) \big),
\end{gather}
where
\begin{gather*}
 x^{1}(t) = a_{1}\sin ( 2c_{3}t) +a_{2}\cos (2c_{3}t) +d_{1}, \\
x^{2}(t) = -a_{2}\sin ( 2c_{3}t) +a_{1}\cos (2c_{3}t) +d_{2}, \\
x^{3}(t) =( a_{2}d_{1}+a_{1}d_{2}) \sin (2c_{3}t) +( a_{2}d_{2}-a_{1}d_{1}) \cos (
2c_{3}t)+2c_{3}\big( a_{1}^{2}+a_{2}^{2}\big) t+d_{3}.
\end{gather*}
Hence $k(t) =-\frac{1}{[ ( a_{1}^{2}+a_{2}^{2}) ] ^{\frac{1}{2}}}<0$ and $\tau (t) =0;$ f\/inally, when $c_{3}< 0$, one has
\begin{gather}\label{gode2}
x(t) = \big( x^{1}(t) ,x^{2}(t),x^{3}(t) \big),
\end{gather}
where
\begin{gather*}
x^{1}(t) = a_{1}\sin (-2c_{3}t) +a_{2}\cos (-2c_{3}t) +d_{1}, \\
x^{2}(t) = a_{2}\sin (-2c_{3}t) -a_{1}\cos (-2c_{3}t) +d_{2}, \\
x^{3}(t) = ( a_{1}d_{1}+a_{2}d_{2}) \sin (-2c_{3}t) -( a_{2}d_{1}-a_{1}d_{2}) \cos (
-2c_{3}t)+2c_{3}\big( a_{1}^{2}+a_{2}^{2}\big) t+d_{3}.
\end{gather*}
Hence $k(t) =\frac{1}{[ ( a_{1}^{2}+a_{2}^{2})  
] ^{\frac{1}{2}}}>0$ and $\tau (t) =0$.

The calculations above show that a horizontal curve is congruent to a geodesic
if it has positive constant $p$-curvature. Conversely, it is easy to prove
that any geodesic acted by a symmetry is still a geodesic. Therefore we
complete the proof of Theorem \ref{chaofgeo}.

\label{norcor}
The normal coordinates are determined up to a transformation of the form
\begin{gather*}
\widetilde{u} =\pm u+g(v), \qquad \widetilde{v} =h(v),
\end{gather*}
for some smooth functions $g(v)$, $h(v)$ with $\frac{\partial h}{\partial v}\neq 0$.

uppose that $(\widetilde{u},\widetilde{v})$ is any normal coordinates around $p$, i.e.,
\begin{gather*}
F_{\widetilde{u}}=\widetilde{X},
\end{gather*}
where $\widetilde{X}=\pm X$. We have the formula for the change of the coordinates
\begin{gather}
F_{u}=F_{\widetilde{u}}\frac{\partial \widetilde{u}}{\partial u}+F_{\widetilde{v}}\frac{\partial \widetilde{v}}{\partial u}, \qquad
F_{v}=F_{\widetilde{u}}\frac{\partial \widetilde{u}}{\partial v}+F_{\widetilde{v}}\frac{\partial \widetilde{v}}{\partial v}.\label{tlofnorpar}
\end{gather}
Expand $F_{\widetilde{v}}=\widetilde{a}\widetilde{X}+\widetilde{b}\widetilde{
Y}+\widetilde{c}\widetilde{T}$ by the orthonormal basis $\{\widetilde{X},\widetilde{Y},\widetilde{T} \}$. The f\/irst identity of~\eqref{tlofnorpar} implies
\begin{gather}
X=F_u=\widetilde{X}\frac{\partial \widetilde{u}}{\partial u}+\left(\widetilde{a}\frac{\partial \widetilde{v}}{\partial u}\widetilde{X} +\widetilde{b}\frac{ 
\partial \widetilde{v}}{\partial u}\widetilde{Y}+\widetilde{c}\frac{\partial\widetilde{v}}{\partial u}\widetilde{T}\right)  =\left(\frac{\partial \widetilde{u}}{\partial u}+\widetilde{a}\frac{\partial \widetilde{v}}{\partial u}\right)\widetilde{X}+ \widetilde{b}\frac{\partial \widetilde{v}}{\partial u}\widetilde{Y}+\widetilde{c}\frac{\partial\widetilde{v}}{\partial u}\widetilde{T}.\!\!\!\!\!\label{tlofnorpar2}
\end{gather}
Since $p$ is a non-singular point, we see that $\widetilde{c}\neq 0$ around $p$, and so
\begin{gather*}
\frac{\partial \widetilde{v}}{\partial u}=0,
\end{gather*}
namely, $ \widetilde{v}=h(v)$
for some function $h(v)$. In addition, comparing the coef\/f\/icient of $X$ in~\eqref{tlofnorpar}, \eqref{tlofnorpar2}, we
have
\begin{gather*}
\pm 1=\frac{\partial \widetilde{u}}{\partial u}+\widetilde{a}\frac{\partial\widetilde{v}}{\partial u}=\frac{\partial \widetilde{u}}{\partial u},
\end{gather*}and hence $\widetilde{u}=\pm u+g(v)$ for some function $g(v)$. Finally we
compute
\begin{gather*}
\det{\left( 
\begin{matrix}
\frac{\partial \widetilde{u}}{\partial u} & \frac{\partial \widetilde{u}}{ 
\partial v} \vspace{1mm}\\
\frac{\partial \widetilde{v}}{\partial u} & \frac{\partial \widetilde{v}}{ 
\partial v} 
\end{matrix} 
\right)}=\det{\left( 
\begin{matrix}
