uppose $\widetilde{a}$, $\widetilde{b}$, $\widetilde{c}$, $\widetilde{l}$, $\widetilde{m}$ are the coef\/f\/icients of f\/irst and second kinds with respect to the normal coordinates $(\widetilde{u}$, $\widetilde{v})$. We point out that all such the coef\/f\/icients have the same expression as in~\eqref{coeofform} w.r.t.\ the new coordinates except for $\widetilde{X}=\pm X$ and $\widetilde{Y}=J\widetilde{X}=\pm Y$.

By Lemma~\ref{norcor}, there exists two functions $g(v)$ and $h(v)$ such that
\begin{gather*}
\widetilde{u}=\pm u+g(v), \qquad \widetilde{v}=h(v).
\end{gather*}
Now we compute the transformation laws of those coef\/f\/icients:
\begin{gather}
a=\langle F_{v},X\rangle =\left\langle F_{\widetilde{u}}\frac{\partial \widetilde{u}}{\partial v}+F_{\widetilde{v}}\frac{\partial \widetilde{v}}{\partial v},X\right\rangle=\left\langle \pm X\frac{\partial g}{\partial v}+F_{\widetilde{v}}\frac{\partial h}{\partial v},X\right\rangle
=\pm \left(\frac{\partial g}{\partial v}+\frac{\partial h}{\partial v}
\widetilde{a}\right).\label{tlofc}
\end{gather}
Similarly, we have
\begin{gather} \label{tlofc1}
b=\pm \frac{\partial h}{\partial v}\widetilde{b},\qquad c=\frac{\partial h}{\partial v}\widetilde{c},
\end{gather}
and so
$F_{u}=\pm F_{\widetilde{u}}$ and $F_{uu}=\pm\big(F_{\widetilde{u}\widetilde{u}}\frac{\partial \widetilde{u}}{\partial u}+F_{\widetilde{u}\widetilde{v}}\frac{\partial \widetilde{v}}{\partial u}\big)=F_{\widetilde{u}\widetilde{u}}$. Thus
\begin{gather} \label{tlofc2}
l=\pm \widetilde{l}.
\end{gather}
Similarly
\begin{gather} \label{tlofc3}
m=\frac{\partial g}{\partial v}\widetilde{l}+\frac{\partial h}{\partial v}\widetilde{m}.
\end{gather}
From the transformation laws \eqref{tlofc}, \eqref{tlofc1}, \eqref{tlofc2}, \eqref{tlofc3}, the result \eqref{invariant14} follows.

