\end{gather}
We also have
\begin{gather} \Theta\wedge \omega^1 = ({\rm d}z+x{\rm d}y-y{\rm d}x)\wedge\langle {\rm d}\mathbb{X},e_1\rangle \nonumber \\
\hphantom{\Theta\wedge \omega^1}{} =\big( (z_u+xy_u-yx_u){\rm d}u+(z_v+xy_v-yx_v){\rm d}v\big)\wedge \big( \langle \mathbb{X}_u,e_1\rangle {\rm d}u+\langle \mathbb{X}_v,e_1\rangle {\rm d}v\big) \nonumber\\
\hphantom{\Theta\wedge \omega^1}{}=\langle E,e_1\rangle {\rm d}u\wedge {\rm d}v.\label{thetawtouv}
\end{gather}
Now we integrate the kinematic density ${\rm d}L$ over the set $\mathcal{L}$. By using \eqref{otop}, \eqref{d2to3}, the Stock's theorem, and \eqref{thetawtouv}, we have
\begin{gather}
\int_{\ell\in\mathcal{L},\, \ell\cap\Sigma\neq\varnothing}n(\ell\cap \Sigma){\rm d}L =2\bigg(\int_{D^+}\pi^*{\rm d}L-\int_{D^-}\pi^*{\rm d}L\bigg) \nonumber\\
\hphantom{\int_{\ell\in\mathcal{L},\, \ell\cap\Sigma\neq\varnothing}n(\ell\cap \Sigma){\rm d}L}{}
=2\bigg(\int_{D^+} \omega^2\wedge \omega^2_1 \wedge \Theta-\int_{D^-} \omega^2\wedge \omega^2_1\wedge \Theta \bigg) \nonumber\\
\hphantom{\int_{\ell\in\mathcal{L},\, \ell\cap\Sigma\neq\varnothing}n(\ell\cap \Sigma){\rm d}L}{} =2\bigg(\int_{\partial D^+}\Theta\wedge \omega^1-\int_{\partial D^-}\Theta\wedge \omega^1\bigg)\nonumber\\
\hphantom{\int_{\ell\in\mathcal{L},\, \ell\cap\Sigma\neq\varnothing}n(\ell\cap \Sigma){\rm d}L}{}=2\bigg(\int_{\Gamma^+\cup\Gamma}\Theta\wedge \omega^1 -\int_{\Gamma^-\cup\Gamma}\Theta\wedge \omega^1\bigg),\label{allintegrals}
\end{gather}
where $\Gamma^{\pm}:=\partial D^{\pm}\setminus\Gamma.$ We also point out that the number, $2$, occurs in the f\/irst identity is due to the orientations for each horizontal line.

Next, we show that ${\rm d}u\wedge {\rm d}v=0$ on $\Gamma^{\pm}$. Indeed, by using the coordinates $\{(u,v,\theta)\}$ for the conf\/iguration space $D$, any vector f\/ield def\/ined on $\Gamma^+$ can be represented by $A\wedge\frac{\partial}{\partial \theta}\in \partial \Sigma\times S^1$ for some vector $A$ def\/ined on the tangent bundle $T\partial\Sigma$. The value ${\rm d}u\wedge {\rm d}v$ evaluated on $\Gamma^+$ must be
\begin{gather*}
{\rm d}u\wedge {\rm d}v\left(A\wedge \frac{\partial}{\partial\theta}\right)={\rm d}u(A){\cancel{{\rm d}v\left(\frac{\partial}{\partial\theta}\right)}}^{\ =0}-{\rm d}v(A){\cancel{{\rm d}u\left(\frac{\partial}{\partial\theta}\right)}}^{\ =0}=0.
\end{gather*}
Therefore, \eqref{allintegrals} becomes
\begin{gather*}
\int_{\ell\in\mathcal{L},\, \ell\cap\Sigma\neq\varnothing}n(\ell\cap \Sigma){\rm d}L =2\bigg( 2\int_{\Gamma}\Theta\wedge \omega^1 +\int_{\Gamma^+}\Theta\wedge \omega^1-\int_{\Gamma^-}\Theta\wedge \omega^1 \bigg)\\
\hphantom{\int_{\ell\in\mathcal{L},\, \ell\cap\Sigma\neq\varnothing}n(\ell\cap \Sigma){\rm d}L}{} =4\int_\Gamma\Theta\wedge \omega^1 =4\int_{\Gamma}|E|{\rm d}u\wedge {\rm d}v=4\cdot \operatorname{p-area}(\Sigma),
\end{gather*} we have used \eqref{thetawtouv} and $E$ is parallel to $e_1$ on $\Gamma$ at the third equality.
